// Use the WASM-based Prisma client with the pg driver adapter.
// This avoids needing the native libquery_engine-*.so.node binary,
// which cannot be downloaded via the agent proxy (binaries.prisma.sh → 403).
// The wasm.js file is generated by `prisma generate` with the driverAdapters
// preview feature enabled, and is patched to load the .wasm file via fs.readFileSync.
import { createRequire } from "module";
import type { PrismaClient } from "@prisma/client";
import { Pool } from "pg";
import { PrismaPg } from "@prisma/adapter-pg";

// createRequire lets us load CommonJS modules from an ESM/TypeScript context.
const _require = createRequire(import.meta.url);
// eslint-disable-next-line @typescript-eslint/no-unsafe-assignment
const { PrismaClient: WasmPrismaClient } = _require(".prisma/client/wasm.js");

// Prevents creating a new Prisma connection on every hot-reload in dev.
const globalForPrisma = global as unknown as { prisma: PrismaClient };

function makePrisma(): PrismaClient {
  const pool = new Pool({ connectionString: process.env.DATABASE_URL });
  const adapter = new PrismaPg(pool);
  // eslint-disable-next-line @typescript-eslint/no-unsafe-call
  return new WasmPrismaClient({
    adapter,
    log: process.env.NODE_ENV === "development" ? ["query", "error"] : ["error"],
  }) as PrismaClient;
}

export const prisma: PrismaClient = globalForPrisma.prisma || makePrisma();

if (process.env.NODE_ENV !== "production") globalForPrisma.prisma = prisma;
